 $('filterSummary').innerHTML=`<span>${view==='menu'&&menuAllMeals?'全部餐次':mealNames[filters.meal]} · ${view==='draw'?candidates().filter(d=>isRecommendable(d,filters.meal)).length:candidates().length} 道符合条件</span>${chips.join('')}${countFilters()?'<button class="text-button" data-action="clear-filters">清除筛选</button>':''}`;
