function renderToday(){return `<div class="today-grid">${Object.entries(mealNames).map(([meal,name])=>{const key=dayKey()+':'+meal,e=state.decisions[key],d=e&&dishById.get(e.dishId);return `<article class="meal-ticket"><div class="meal-label"><span>${name}饭票</span>${icon('bowl')}</div><h3>${e?esc(e.snapshot.name):'还没有决定'}</h3><p>${e?`${!isPublished(d)?'灵感已归档':!isRecommendable(d,meal)?(d.mealSuitability?.note||'原决定保留，建议补充主食或搭配'):e.eatenAt?'已记入用餐记录':'决定好了，等着开饭'}`:'去选一餐，或者先留一点期待。'}</p>${e?`${!e.eatenAt?`<button class="button secondary" data-action="eaten" data-key="${key}">我吃过了</button>`:'<span class="small muted">已经认真吃过了</span>'}<button class="text-button" data-action="cancel-decision" data-key="${key}">取消决定</button>`:`<button class="button secondary" data-action="choose-meal" data-value="${meal}">选${name}${icon('arrow')}</button>`}</article>`;}).join('')}</div><div class="section-head"><h2>今天先跳过</h2>${state.excluded.ids.length?'<button class="text-button" data-action="restore-all">全部恢复</button>':''}</div>${state.excluded.ids.length?state.excluded.ids.map(id=>`<div class="unavailable"><span>${esc(dishById.get(id)?.name??'旧版餐品')}</span><button class="text-button" data-action="restore" data-id="${id}">恢复</button></div>`).join(''):'<p class="muted">还没有跳过的餐品。当天跳过只影响当天，次日自动恢复。</p>'}`;}
function renderPlan(){const days=Array.from({length:7},(_,i)=>addDays(planStart,i));return `<div class="plan-controls"><div><h2>这一周，提前想好</h2><p class="small muted">生成计划遵守当前筛选；锁定的餐次保持不变。</p></div><label>周起始日 <input id="planStart" type="date" value="${planStart}"></label><button class="button primary" data-action="generate-plan">${icon('shuffle')}生成未锁定餐次</button></div><div class="plan-grid">${days.map(date=>`<section class="plan-day"><h3 class="plan-date">${date.slice(5).replace('-','/')} ${['周日','周一','周二','周三','周四','周五','周六'][new Date(date+'T12:00:00+08:00').getUTCDay()]}</h3>${Object.entries(mealNames).map(([meal,name])=>{const key=date+':'+meal,x=state.plan[key],d=dishById.get(x?.dishId);return `<div class="plan-slot ${x?.locked?'locked':''}"><small>${name}${x?.locked?' · 已锁定':''}</small><strong>${d?esc(d.name):'还未安排'}</strong><small>${esc(x?.notice||(!d?'从主餐灵感里挑选':!isPublished(d)?'已归档，原计划保留':!isRecommendable(d,meal)?(d.mealSuitability?.note||'原计划保留，建议补充搭配'):''))}</small><div class="slot-actions"><button class="text-button" data-action="plan-lock" data-key="${key}" ${!x?'disabled':''}>${x?.locked?'解锁':'锁定'}</button><button class="text-button" data-action="plan-picker" data-key="${key}">替换</button><button class="text-button" data-action="plan-reroll" data-key="${key}" ${x?.locked?'disabled':''}>重选</button>${date===dayKey()&&isRecommendable(d,meal)?`<button class="text-button" data-action="plan-decide" data-key="${key}">作为今日决定</button>`:''}</div></div>`;}).join('')}</section>`).join('')}</div><p class="small muted" style="margin-top:18px">计划不等于已经吃过。实际用餐只在你确认后记录；候选不足时允许重复，没有候选时保留空位。</p>`;}
function renderFavorites(){const folder=state.collections.find(c=>c.id===activeFolder)??state.collections[0];activeFolder=folder.id;const ids=folder.id==='default'?state.favorites:folder.ids,available=ids.map(id=>dishById.get(id)).filter(d=>isPublished(d)),archived=ids.filter(id=>!isPublished(dishById.get(id)));return `<div class="folder-controls"><label class="sr-only" for="folderSelect">选择收藏夹</label><select id="folderSelect">${state.collections.map(c=>`<option value="${esc(c.id)}" ${c.id===activeFolder?'selected':''}>${esc(c.name)}（${c.id==='default'?state.favorites.length:c.ids.length}）</option>`).join('')}</select><button class="text-button" data-action="create-folder">新建收藏夹</button>${activeFolder!=='default'?'<button class="text-button danger" data-action="delete-folder">删除收藏夹</button>':''}</div>${available.length?`<div class="menu-grid">${available.map(d=>card(d,{folder:true})).join('')}</div>`:empty('把想吃的，慢慢收好','收藏的餐品会留在这里。已归档的旧收藏也会保留，随时可查看。','<a class="button secondary" href="#/menu">去逛菜单</a>')}${archived.length?'<h3 style="margin-top:22px">暂不可推荐的收藏</h3>'+archived.map(id=>`<div class="unavailable"><span>${dishById.has(id)?`<button class="text-button" data-action="detail" data-id="${esc(id)}">${esc(dishById.get(id).name)}</button>`:'已移除餐品'}<small>灵感已归档，原收藏保留</small></span><button class="text-button" data-action="favorite" data-id="${esc(id)}">取消收藏</button></div>`).join(''):''}`;}
function renderHistory(){const items=state.history.filter(e=>!selectedDate||e.date===selectedDate),types=new Set(state.history.map(e=>dishById.get(e.dishId)?.category).filter(Boolean));return `<div class="stats"><span><strong>${state.history.length}</strong>次实际用餐</span><span><strong>${new Set(state.history.map(e=>e.dishId)).size}</strong>道尝试过的餐品</span><span><strong>${types.size}</strong>种分类</span></div>${calendarMarkup(calendarMonth,state.history,selectedDate)}<div class="history-controls"><label>查看日期 <input type="date" id="historyDate" value="${selectedDate}"></label>${selectedDate?'<button class="text-button" data-action="all-history">查看全部日期</button>':''}</div>${items.length?items.map(e=>`<div class="history-row"><div>${e.date}<br>${mealNames[e.meal]}</div><div class="history-name"><strong>${esc(e.snapshot.name)}</strong>${e.snapshot.restaurant&&e.snapshot.restaurant!=='餐厅未指定'?`<small>原记录：${esc(e.snapshot.restaurant)}</small>`:''}</div><label class="rating-label">评分 <select data-rating="${esc(e.dishId)}" aria-label="为${esc(e.snapshot.name)}评分"><option value="0">未评分</option>${[1,2,3,4,5].map(r=>`<option value="${r}" ${state.ratings[e.dishId]===r?'selected':''}>${r} 分</option>`).join('')}</select></label><button class="text-button danger" data-action="delete-history" data-value="${esc(e.id)}">删除</button></div>`).join(''):empty(selectedDate?'这天还没有用餐记录':'把认真吃过的每一餐，记下来','“就吃这个”只保存决定；点击“我吃过了”才会写入记录。')}<p class="small muted" style="margin-top:15px">统计只来自你自己的饭本，最多保留最近200条实际用餐记录。</p>`;}
